import React, { useState } from 'react';
import axios from 'axios';
import { Link, useNavigate } from 'react-router-dom';

function UserSignup() {
  const [formData, setFormData] = useState({
    account_number: '',
    password: '',
  });
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const navigate = useNavigate();

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleSignup = async (e) => {
    e.preventDefault();
    if (!formData.account_number || !formData.password) {
      setError('Account Number and Password are required.');
      return;
    }
    try {
      const response = await axios.post('http://localhost:3001/user/signup', formData);
      if (response.data.success) {
        setSuccess(response.data.message);
        setTimeout(() => navigate('/'), 2000);
      } else {
        setError(response.data.message);
      }
    } catch (err) {
      setError('Failed to sign up. Please try again.');
    }
  };

  return (
    <div className="p-8 max-w-md mx-auto">
      <h2 className="text-2xl font-bold mb-4">User Sign Up</h2>
      {error && <p className="text-red-500 mb-4">{error}</p>}
      {success && <p className="text-green-500 mb-4">{success}</p>}
      <form onSubmit={handleSignup}>
        <input
          type="text"
          name="account_number"
          placeholder="Account Number"
          value={formData.account_number}
          onChange={handleInputChange}
          className="w-full p-2 mb-2 border rounded"
        />
        <input
          type="password"
          name="password"
          placeholder="Password"
          value={formData.password}
          onChange={handleInputChange}
          className="w-full p-2 mb-2 border rounded"
        />
        <button
          type="submit"
          className="w-full bg-blue-500 text-white p-2 rounded hover:bg-blue-600"
        >
          Sign Up
        </button>
      </form>
      <p className="mt-4">
        Already have an account? <Link to="/" className="text-blue-500">Login</Link>
      </p>
    </div>
  );
}

export default UserSignup;
